const {$,esc,fmt,api,toast,modal,closeModal}=window;
const state={page:'dashboard',projects:[],projectId:null,projectTab:'overview',candidateId:null,candidateSection:'evidence',candidateReturnTab:'candidates',providers:null,health:false,candidateQuery:'',candidateArchive:'active',candidateMaterial:'all',candidateStage:'all',candidatePage:0,candidateLimit:25,candidateRows:[],taskStatus:'',taskType:'',taskPage:0,taskLimit:50,cockpitPage:0,cockpitLimit:25,auditOffset:0,flowQuery:'',handoffPayload:null,jobSetupStep:1,jobSetupDraft:null,jobSetupSuggestions:[],criteriaStageDefs:[],criteriaRecruitmentContext:{},criteriaDecisionPolicy:{},criteriaBrief:{},criteriaOriginalByKey:{}};
// Ephemeral drafts survive in-flight workbench redraws but never leave this browser session.
const materialDrafts=new Map();
window.state=state;window.materialDrafts=materialDrafts;
// Inline event-handler attributes (onclick/onchange) resolve in global scope, but these page
// entry points are module-scoped. Expose them explicitly so injected handlers resolve;
// scripts/check_frontend_contract.py fails the source gate if a handler reference is unassigned.
window.renderPage=renderPage;window.projectWorkspace=projectWorkspace;
// Inline handlers also mutate module state; the wrappers below own that mutation so the
// attributes stay global-scope-safe. scripts/check_frontend_contract.py fails the gate
// on any handler that still references a module-scope binding directly.
window.selectFlowCandidate=el=>{state.candidateId=el.value;return projectWorkspace()};
window.filterCandidatesByStage=k=>{state.candidateStage=k;return setProjectTab('candidates')};
function statusClass(s){if(['succeeded','confirmed','published','ready','active','open','hired','accepted','completed','approved'].includes(s))return'good';if(['failed','rejected','conflict','declined','withdrawn','cancelled','closed'].includes(s))return'bad';if(['waiting_provider','draft','missing','partial','paused','offer','scheduled','shortlisted'].includes(s))return'warn';return'info'}
const stageLabels={new:'新候选人',screening:'简历筛选',shortlisted:'短名单',phone_screen:'电话筛选',interview:'面试',offer:'Offer',hired:'录用',rejected:'拒绝',talent_pool:'人才池',withdrawn:'候选人退出'};const projectStatusLabels={draft:'草案',open:'招聘中',paused:'暂停招聘',filled:'已招满',closed:'已关闭',archived:'已归档'};const offerLabels={draft:'草案',approved:'已批准',sent:'已发送',accepted:'已接受',declined:'已拒绝',withdrawn:'已撤回'};function stageLabel(s){return stageLabels[s]||s||'—'};const workbenchActionLabels={RESOLVE_CONFLICT:'处理证据冲突',VERIFY_CRITERION:'核实评价标准',RUN_SCREEN:'完成简历筛选',PREPARE_INTERVIEW:'准备结构化面试',REVIEW_REEVALUATION:'复核重新评价',MAKE_DECISION:'提交人工决定'};function workbenchActionLabel(s){return workbenchActionLabels[s]||s||'待处理'}
const icons={dashboard:'▦',projects:'▣',templates:'▤',knowledge:'⌕',tasks:'⟳',settings:'⚙'};
function shell(){return `<div class="app-shell"><aside class="sidebar"><div class="logo"><div class="logo-mark">SRW</div><div><strong>智能招聘工作台</strong><small>v1.0 Convergence 11 · Business Workflow Closure</small></div></div><div class="nav-group">Recruitment OS</div>${[['dashboard','工作台总览'],['projects','招聘项目'],['templates','岗位模板'],['knowledge','知识库'],['tasks','后台任务'],['settings','系统设置']].map(([k,l])=>`<button class="nav-item ${state.page===k?'active':''}" onclick="go('${k}')"><span class="nav-icon">${icons[k]}</span><span>${l}</span></button>`).join('')}<div class="side-footer">本地优先 · 业务闭环 · 证据可追溯<br>AI 建议 ≠ 人工决定<br><span id="side-health">正在检查服务…</span></div></aside><main class="main"><header class="topbar"><div class="top-title" id="top-title"></div><div class="top-right"><span id="service-health-badge" class="badge" role="status" aria-live="polite"><span id="service-health-dot" class="dot ${state.health?'good':''}"></span><span id="service-health-text">${state.health?'服务正常':'服务检查中'}</span></span><span class="badge">v1_0014</span></div></header><div class="content" id="content"></div></main></div>`}
window.go=async p=>{state.page=p;state.candidateId=null;state.candidateSection='evidence';document.body.innerHTML=shell()+`<div id="modal-root"></div><div id="toast-root"></div>`;await renderPage()};window.openWorkbenchItem=async(pid,cid,type)=>{state.page='projects';state.projectId=pid;state.candidateReturnTab=type==='PREPARE_INTERVIEW'?'flow':'cockpit';state.projectTab=state.candidateReturnTab;state.candidateId=type==='PREPARE_INTERVIEW'?null:cid;state.candidateSection='evidence';document.body.innerHTML=shell()+`<div id="modal-root"></div><div id="toast-root"></div>`;await renderPage()};window.openOperationalItem=async(kind,pid,cid,eid)=>{state.page='projects';state.projectId=pid;state.candidateReturnTab='overview';state.projectTab=kind==='pending_interview_feedback'?'flow':'overview';state.candidateId=['overdue_contact','today_contact'].includes(kind)?(cid||null):null;state.candidateSection='process';document.body.innerHTML=shell()+`<div id="modal-root"></div><div id="toast-root"></div>`;await renderPage();if(['overdue_contact','today_contact'].includes(kind)&&cid)await openActionPlan(cid);if(kind==='pending_interview_feedback'&&eid)await openScorecards(eid)};window.openReviewItem=async(kind,pid,cid,reviewId='',claimId='')=>{
  state.page='projects';state.projectId=pid;state.candidateReturnTab='quality';
  state.projectTab=kind==='unreviewed_claim'?'candidates':'quality';
  state.candidateId=kind==='unreviewed_claim'?(cid||null):null;
  state.candidateSection='evidence';
  document.body.innerHTML=shell()+`<div id="modal-root"></div><div id="toast-root"></div>`;
  await renderPage();
  const focusId=kind==='unreviewed_claim'?(claimId?'srw-claim-'+claimId:''):(reviewId?'srw-review-'+reviewId:'');
  if(!focusId)return;
  const target=document.getElementById(focusId);
  if(!target){toast('该复核项可能已处理或不在当前页面，请核对队列。',true);return}
  target.classList.add('review-item-focused');
  target.scrollIntoView({block:'center',behavior:'auto'});
  const button=target.querySelector('button');
  if(button)button.focus({preventScroll:true});
};
async function init(){document.body.innerHTML=shell()+`<div id="modal-root"></div><div id="toast-root"></div>`;try{await api('/health/ready');state.health=true}catch{}await renderPage();}
async function renderPage(){const t={dashboard:'工作台总览',projects:'招聘项目',templates:'岗位模板',knowledge:'知识库',tasks:'后台任务',settings:'系统设置'}[state.page]||'工作台';$('#top-title').textContent=t;if($('#side-health'))$('#side-health').textContent=state.health?'服务已就绪 · 本地数据':'服务状态待确认';const healthText=$('#service-health-text'),healthDot=$('#service-health-dot');if(healthText)healthText.textContent=state.health?'服务正常':'服务检查中';if(healthDot)healthDot.classList.toggle('good',Boolean(state.health));const fn={dashboard:window.dashboardPage,projects:projectsPage,templates:window.templatesPage,knowledge:window.knowledgePage,tasks:window.tasksPage,settings:window.settingsPage}[state.page];try{await fn()}catch(e){$('#content').innerHTML=`<div class="panel"><div class="panel-body empty"><strong>页面加载失败</strong>${esc(e.message)}</div></div>`}}
function head(title,desc,actions=''){return `<div class="page-head"><div><h1>${title}</h1><p>${desc}</p></div><div class="actions">${actions}</div></div>`}
async function projectsPage(){const d=await api('/api/v1/projects');state.projects=d.projects||[];if(state.projectId){return projectWorkspace()}$('#content').innerHTML=head('招聘项目','把每个招聘项目作为一条职位生命周期管理：草案 → 招聘中 → 暂停 / 招满 / 关闭。',`<button class="btn" onclick="c08OpenProjectImport()">导入完整项目包</button><button class="btn primary" onclick="openNewProject()">＋ 新建项目</button>`)+`<section class="panel"><div class="panel-head"><h2>职位生命周期</h2><span class="subtle">${state.projects.length} 个项目</span></div><div class="table-wrap"><table class="table"><thead><tr><th>项目 / 职位</th><th>招聘状态</th><th>标准</th><th>候选人</th><th>待办</th><th></th></tr></thead><tbody>${state.projects.length?state.projects.map(p=>`<tr><td><strong>${esc(p.title)}</strong><div class="subtle">${esc(p.protocol_title||'—')}</div></td><td><span class="status ${statusClass(p.status)}">${esc(projectStatusLabels[p.status]||p.status)}</span></td><td><span class="status ${statusClass(p.protocol_state)}">${esc(p.protocol_state)}</span></td><td>${p.candidate_count}</td><td>${p.open_work_count}</td><td class="right"><button class="btn small primary" onclick="openProject('${p.project_id}')">进入工作区</button></td></tr>`).join(''):`<tr><td colspan="6"><div class="empty"><strong>还没有招聘项目</strong>先新建职位，再发布招聘标准。</div></td></tr>`}</tbody></table></div></section>`}
window.openProject=async id=>{state.projectId=id;state.projectTab='overview';state.candidateId=null;state.candidateSection='evidence';await projectsPage()};window.closeProject=async()=>{state.projectId=null;state.candidateId=null;state.candidateSection='evidence';await projectsPage()};window.setProjectTab=async t=>{state.projectTab=t;state.candidateId=null;state.candidateSection='evidence';await projectWorkspace()};
function projectTabs(){return [['overview','项目首页'],['criteria','建岗与标准'],['candidates','候选人收件'],['cockpit','筛选与决策'],['flow','面试流程'],['ops','跟进运营'],['quality','质量复核'],['audit','版本与审计']].map(([k,l])=>`<button class="tab ${state.projectTab===k?'active':''}" onclick="setProjectTab('${k}')">${l}</button>`).join('')}
async function projectWorkspace(){const p=state.projects.find(x=>x.project_id===state.projectId)||{};if(state.candidateId){await candidateDrawer(state.candidateId,p);return}$('#content').innerHTML=`<div class="project-banner"><div><button class="btn small" onclick="closeProject()">← 返回项目列表</button><h2>${esc(p.title||'项目工作区')}</h2><div class="project-meta"><span class="badge">岗位：${esc(p.protocol_title||'—')}</span><span class="badge">状态：${esc(projectStatusLabels[p.status]||p.status||'—')}</span><span class="badge">协议：${esc(p.protocol_state||'—')}</span><span class="badge">候选人：${p.candidate_count||0}</span></div></div><div class="actions"><button class="btn" onclick="openProjectStatus('${p.status||'draft'}')">职位生命周期</button><button class="btn" onclick="archiveProject('${state.projectId}')">归档项目</button></div></div><div class="panel"><div class="tabs">${projectTabs()}</div><div class="panel-body" id="project-tab-body"><div class="empty">加载中…</div></div></div>`;const fn={overview:projectOverview,criteria:window.criteriaTab,cockpit:cockpitTab,candidates:window.candidatesTab,flow:window.flowTab,ops:async(el,p)=>window.operationsLearningTab(el,p),quality:qualityTab,audit:auditTab}[state.projectTab];try{await fn($('#project-tab-body'),p)}catch(e){$('#project-tab-body').innerHTML=`<div class="empty"><strong>加载失败</strong>${esc(e.message)}</div>`}}
window.openProjectStatus=current=>modal('职位生命周期',`<div class="field"><label>职位状态</label><select id="project-status" class="select">${[['draft','草案'],['open','招聘中'],['paused','暂停招聘'],['filled','已招满'],['closed','关闭职位']].map(([v,l])=>`<option value="${v}" ${v===current?'selected':''}>${l}</option>`).join('')}</select></div><div class="field" style="margin-top:10px"><label>变更理由</label><textarea id="project-status-reason" class="textarea" placeholder="例如：HC 已批准 / 暂停招聘 / 已完成录用"></textarea></div>`,`<button class="btn" onclick="closeModal()">取消</button><button class="btn primary" onclick="saveProjectStatus()">确认变更</button>`);window.saveProjectStatus=async()=>{try{await api(`/api/v1/projects/${state.projectId}/status`,{method:'POST',body:JSON.stringify({status:$('#project-status').value,reason:$('#project-status-reason').value||'人工更新职位状态',actor:'human'})});closeModal();toast('职位状态已更新');await refreshProjects();await projectWorkspace()}catch(e){toast(e.message,true)}};
window.archiveProject=async id=>{if(!confirm('归档该项目？数据不会删除。'))return;try{await api(`/api/v1/projects/${id}/archive`,{method:'POST'});state.projectId=null;toast('项目已归档');await projectsPage()}catch(e){toast(e.message,true)}};
async function projectOverview(el,p){const [pipe,proto]=await Promise.all([api(`/api/v1/projects/${state.projectId}/pipeline`),api(`/api/v1/projects/${state.projectId}/protocol-workspace`).catch(()=>null)]);const s=pipe.stages||{},o=pipe.offers_by_status||{};const w=pipe.workflow_summary||{next_action:{tab:'candidates',label:'继续推进候选人',reason:''}};el.innerHTML=`<div class="actions" style="margin-bottom:12px"><button class="btn primary" onclick="openContactWorkbench()">联系工作台</button><button class="btn" onclick="openRankedShortlist('${state.projectId}')">证据短名单</button><button class="btn" onclick="openProjectAiRuns('${state.projectId}')">AI 运行账本</button><button class="btn" onclick="openHandoff()">项目交接摘要</button><button class="btn" onclick="c08ExportProjectPackage('${state.projectId}')">完整项目包</button><a class="btn" href="/api/v1/projects/${state.projectId}/contact-list.csv">电话联系清单</a></div><div class="grid kpi">${[['候选人',pipe.total_candidates,'当前项目全部在库候选人'],['短名单',s.shortlisted||0,'待电话筛选 / 面试'],['近期面试',pipe.upcoming_interviews||0,'已排期未完成'],['Offer',Object.values(o).reduce((a,b)=>a+Number(b||0),0),'草案到接受的完整状态']].map(x=>`<div class="kpi-card"><div class="kpi-label">${x[0]}</div><div class="kpi-value">${x[1]}</div><div class="kpi-note">${x[2]}</div></div>`).join('')}</div><section class="panel"><div class="panel-head"><h3>招聘漏斗</h3><span class="status ${statusClass(pipe.project_status)}">${esc(projectStatusLabels[pipe.project_status]||pipe.project_status)}</span></div><div class="panel-body"><div class="funnel-grid">${['new','screening','shortlisted','phone_screen','interview','offer','hired'].map(k=>`<button class="funnel-step clickable" onclick="filterCandidatesByStage('${k}')"><strong>${s[k]||0}</strong><span>${stageLabel(k)}</span></button>`).join('')}</div><div class="pill-row" style="margin-top:12px"><span class="status info">人才池 ${s.talent_pool||0}</span><span class="status bad">拒绝 ${s.rejected||0}</span><span class="status">退出 ${s.withdrawn||0}</span></div></div></section><div class="two"><section class="panel"><div class="panel-head"><h3>近期面试</h3><button class="btn small" onclick="setProjectTab('flow')">招聘流程</button></div><div class="panel-body">${pipe.scheduled_events?.length?`<div class="quick-list">${pipe.scheduled_events.slice(0,6).map(x=>`<div class="quick-item"><div><div class="quick-title">${esc(x.candidate_name)} · ${esc(x.title||x.event_type)}</div><div class="quick-note">${new Date(x.scheduled_at).toLocaleString()} · ${esc(x.interviewer||'待指定面试官')} · ${esc(x.location||'待指定地点')}</div></div><span class="status warn">已排期</span></div>`).join('')}</div>`:'<div class="empty">近期没有已排期面试</div>'}</div></section><section class="panel"><div class="panel-head"><div><h3>项目推进</h3><span class="subtle">系统根据当前真实业务状态给出一个优先动作，不替代人工招聘判断。</span></div></div><div class="panel-body"><div class="quick-list"><div class="quick-item"><span>招聘标准</span><strong>${w.criteria_published?'已发布':'待发布'}</strong></div><div class="quick-item"><span>候选人 / 缺材料</span><strong>${fmt(w.candidate_count||0)} / ${fmt(w.candidates_without_material||0)}</strong></div><div class="quick-item"><span>决策待办 / 待确认事实</span><strong>${fmt(w.decision_work_candidates||0)} / ${fmt(w.unreviewed_claims||0)}</strong></div><div class="quick-item"><span>待反馈面试 / 已排期</span><strong>${fmt(w.pending_interview_feedback||0)} / ${fmt(w.upcoming_interviews||0)}</strong></div><div class="quick-item"><span>Offer 待跟进</span><strong>${fmt(w.offer_followups||0)}</strong></div></div><div class="provider-card" style="margin-top:12px"><div class="provider-title"><div><h3>${esc(w.next_action?.label||'继续推进候选人')}</h3><div class="provider-sub">${esc(w.next_action?.reason||'')}</div></div><button class="btn primary" onclick="setProjectTab('${w.next_action?.tab||'candidates'}')">现在处理</button></div></div></div></section></div>`}

async function cockpitTab(el,p){const d=await api(`/api/v1/projects/${state.projectId}/cockpit?limit=${state.cockpitLimit}&offset=${state.cockpitPage*state.cockpitLimit}`);const pages=Math.max(1,Math.ceil(d.total/state.cockpitLimit));el.innerHTML=`<div class="panel-head" style="padding:0 0 12px;border:0"><div><h3>决策驾驶舱 <span class="subtle">${d.total} 人</span></h3><span class="subtle">服务端分页聚合；流程阶段与证据记录分开呈现。</span></div><button class="btn primary" onclick="openRankedShortlist('${state.projectId}')">生成证据短名单</button></div><div class="table-wrap"><table class="table"><thead><tr><th>候选人</th><th>阶段</th><th>岗位匹配</th><th>证据覆盖</th><th>材料</th><th>已确认事实</th><th>待确认</th><th>当前判断项</th><th></th></tr></thead><tbody>${d.candidates.map(c=>`<tr><td><strong>${esc(c.display_name)}</strong></td><td><span class="status ${statusClass(c.pipeline_stage)}">${stageLabel(c.pipeline_stage)}</span></td><td>${c.assessment?.fit_score==null?'<span class="subtle">待证据闭合</span>':`<strong>${c.assessment.fit_score}%</strong>`}</td><td>${c.assessment?`${Math.round(Number(c.assessment.evidence_coverage||0)*100)}%`:'—'}</td><td>${c.has_material?'已导入':'待上传'}</td><td>${c.confirmed_claims}</td><td>${c.unreviewed_claims}</td><td>${c.judgments}</td><td><button class="btn small primary" onclick="openCandidate('${c.candidate_id}')">查看工作区</button></td></tr>`).join('')}</tbody></table></div><div class="actions" style="justify-content:flex-end;margin-top:12px"><button class="btn small" ${state.cockpitPage<=0?'disabled':''} onclick="cockpitPage(-1)">上一页</button><span class="subtle">第 ${state.cockpitPage+1} / ${pages} 页</span><button class="btn small" ${(state.cockpitPage+1)>=pages?'disabled':''} onclick="cockpitPage(1)">下一页</button></div>`}
window.cockpitPage=d=>{state.cockpitPage=Math.max(0,state.cockpitPage+d);projectWorkspace()};
async function qualityTab(el,p){const [idq,anchors,reviews]=await Promise.all([api(`/api/v1/projects/${state.projectId}/identity-reviews`),api(`/api/v1/projects/${state.projectId}/calibration/anchors`),api(`/api/v1/projects/${state.projectId}/calibration/reviews`)]);const all=idq.reviews||[],pending=all.filter(x=>x.status==='pending'),mergeReady=all.filter(x=>x.status==='confirmed_same'&&!x.merge_performed),merged=all.filter(x=>x.merge_performed);el.innerHTML=`<div class="two"><section><div class="panel-head" style="padding:0 0 10px;border:0"><h3>候选人身份复核</h3><button class="btn primary" onclick="scanIdentity()">扫描重复身份</button></div><p class="subtle">精确邮箱/电话只用于发现候选重复线索。必须先人工确认“同一人”，再进入 Merge Preview；系统不会静默自动合并。</p>${pending.length?pending.map(x=>`<div class="quick-item" id="srw-review-${esc(x.review_id)}"><div><div class="quick-title">${esc(x.candidate_a.display_name)} ↔ ${esc(x.candidate_b.display_name)}</div><div class="quick-note">${esc(x.match_reason)} · 待人工判定</div></div><div class="actions"><button class="btn small primary" onclick="resolveIdentity('${x.review_id}','confirmed_same')">同一人</button><button class="btn small" onclick="resolveIdentity('${x.review_id}','confirmed_distinct')">不同人</button></div></div>`).join(''):'<div class="empty">没有待处理的身份复核项</div>'}${mergeReady.length?`<h3 style="margin-top:16px">已确认同一人 · 待 canonical merge</h3>${mergeReady.map(x=>`<div class="quick-item"><div><div class="quick-title">${esc(x.candidate_a.display_name)} ↔ ${esc(x.candidate_b.display_name)}</div><div class="quick-note">历史数据不会被重写；合并前必须查看影响预览。</div></div><button class="btn small primary" onclick="openIdentityMerge('${x.review_id}','${x.candidate_a.candidate_id}','${x.candidate_b.candidate_id}')">Merge Preview</button></div>`).join('')}`:''}${merged.length?`<p class="subtle" style="margin-top:12px">已完成 canonical merge：${merged.length} 项。</p>`:''}</section><section><div class="panel-head" style="padding:0 0 10px;border:0"><h3>判断纠错队列</h3><button class="btn" onclick="openJudgmentReview()">＋ 记录纠错</button></div>${(reviews.reviews||[]).filter(x=>x.state==='open').length?(reviews.reviews||[]).filter(x=>x.state==='open').map(x=>`<div class="quick-item" id="srw-review-${esc(x.review_id)}"><div><div class="quick-title">${esc(x.criterion_key)} · ${esc(x.error_class)}${x.candidate_name?` · ${esc(x.candidate_name)}`:' · 项目级'}</div><div class="quick-note">${esc(x.before)} → ${esc(x.after)} · ${esc(x.reason)}</div></div><div class="actions">${x.candidate_id?`<button class="btn small" onclick="openCandidate('${x.candidate_id}')">查看候选人</button>`:''}<button class="btn small primary" onclick="resolveJudgmentReview('${x.review_id}')">完成复核</button></div></div>`).join(''):'<div class="empty">暂无开放的判断纠错项</div>'}</section></div><div class="divider"></div><section><div class="panel-head" style="padding:0 0 10px;border:0"><div><h3>Criterion Anchor Cases</h3><div class="subtle">observed → human_reviewed → candidate → gold；Gold 必须由第二位不同复核者晋级。</div></div><button class="btn primary" onclick="openCreateAnchor()">＋ 新建 Anchor</button></div>${(anchors.anchors||[]).length?`<table class="table"><thead><tr><th>标准</th><th>案例</th><th>期望判断</th><th>证据</th><th>生命周期</th><th></th></tr></thead><tbody>${anchors.anchors.map(x=>`<tr><td>${esc(x.criterion_key)}</td><td>${esc(x.case_text.slice(0,100))}</td><td>${esc(x.expected_judgment)}</td><td>${esc(x.expected_evidence_level)}</td><td><span class="status ${x.lifecycle==='gold'?'good':'info'}">${esc(x.lifecycle)}</span></td><td>${x.lifecycle!=='gold'?`<button class="btn small" onclick="promoteAnchor('${x.anchor_id}','${x.lifecycle}')">晋级</button>`:''}</td></tr>`).join('')}</tbody></table>`:'<div class="empty">尚未建立校准 Anchor Case</div>'}</section>`}window.scanIdentity=async()=>{try{const r=await api(`/api/v1/projects/${state.projectId}/identity-reviews/scan`,{method:'POST',body:JSON.stringify({actor:'human'})});toast(`身份扫描完成：新增 ${r.created} 项`);await projectWorkspace()}catch(e){toast(e.message,true)}};window.resolveIdentity=async(id,status)=>{const note=prompt('复核说明：','人工核对联系方式与材料');if(note===null)return;try{await api(`/api/v1/identity-reviews/${id}/resolve`,{method:'POST',body:JSON.stringify({status,actor:'human',note})});toast(status==='confirmed_same'?'已确认同一人；请进入 Merge Preview 选择 canonical identity':'身份复核已记录');await projectWorkspace()}catch(e){toast(e.message,true)}};window.openJudgmentReview=()=>modal('记录判断纠错',`<div class="form-grid"><div class="field"><label>criterion_key</label><input id="jr-key" class="input"></div><div class="field"><label>触发场景</label><input id="jr-trigger" class="input" value="human_override"></div><div class="field"><label>原判断</label><input id="jr-before" class="input"></div><div class="field"><label>修正后</label><input id="jr-after" class="input"></div><div class="field full"><label>错误分类</label><select id="jr-reason" class="select"><option value="input_error">输入错误</option><option value="evidence_error">证据错误</option><option value="rubric_error">标准设计错误</option><option value="execution_error">执行错误</option><option value="decision_error">决策错误</option><option value="other">其他</option></select></div></div>`,`<button class="btn" onclick="closeModal()">取消</button><button class="btn primary" onclick="saveJudgmentReview()">记录</button>`);window.saveJudgmentReview=async()=>{try{await api(`/api/v1/projects/${state.projectId}/calibration/reviews`,{method:'POST',body:JSON.stringify({trigger:$('#jr-trigger').value,criterion_key:$('#jr-key').value,before:$('#jr-before').value,after:$('#jr-after').value,reason:$('#jr-reason').value,actor:'human'})});closeModal();toast('判断纠错已进入复核队列');await projectWorkspace()}catch(e){toast(e.message,true)}};window.resolveJudgmentReview=async id=>{const note=prompt('复核结论 / 处理说明：','已复核并确认纠错处理');if(!note)return;try{await api(`/api/v1/calibration/reviews/${id}/resolve`,{method:'POST',body:JSON.stringify({actor:'human',note})});toast('判断纠错复核已完成');await projectWorkspace()}catch(e){toast(e.message,true)}};window.openCreateAnchor=()=>modal('新建 Criterion Anchor',`<div class="form-grid"><div class="field"><label>criterion_key</label><input id="an-key" class="input"></div><div class="field"><label>期望判断</label><select id="an-j" class="select">${['met','partial','missing','conflict','not_met'].map(x=>`<option>${x}</option>`).join('')}</select></div><div class="field"><label>期望证据等级</label><select id="an-e" class="select">${['strong','medium','weak','none'].map(x=>`<option>${x}</option>`).join('')}</select></div><div class="field full"><label>案例文本</label><textarea id="an-text" class="textarea"></textarea></div></div>`,`<button class="btn" onclick="closeModal()">取消</button><button class="btn primary" onclick="saveAnchor()">创建</button>`);window.saveAnchor=async()=>{try{await api(`/api/v1/projects/${state.projectId}/calibration/anchors`,{method:'POST',body:JSON.stringify({criterion_key:$('#an-key').value,case_text:$('#an-text').value,expected_judgment:$('#an-j').value,expected_evidence_level:$('#an-e').value,actor:'human'})});closeModal();toast('Anchor 已创建');await projectWorkspace()}catch(e){toast(e.message,true)}};window.promoteAnchor=async(id,current)=>{const order=['observed','human_reviewed','candidate','gold'],target=order[order.indexOf(current)+1],actor=prompt(target==='gold'?'Gold 晋级必须填写与首位复核者不同的复核人：':'复核人：','human');if(!actor)return;try{await api(`/api/v1/calibration/anchors/${id}/promote`,{method:'POST',body:JSON.stringify({target,actor})});toast(`Anchor 已晋级到 ${target}`);await projectWorkspace()}catch(e){toast(e.message,true)}};
async function auditTab(el,p){const limit=25;const d=await api(`/api/v1/projects/${state.projectId}/audit?limit=${limit}&offset=${state.auditOffset}`);el.innerHTML=`<div class="two"><div><h3>协议版本</h3><table class="table"><thead><tr><th>版本</th><th>状态</th><th>创建</th><th>Hash</th></tr></thead><tbody>${d.protocol_revisions.map(x=>`<tr><td>v${x.revision}</td><td><span class="status ${statusClass(x.state)}">${esc(x.state)}</span></td><td>${new Date(x.created_at).toLocaleString()}</td><td class="mono">${esc(x.content_hash.slice(0,12))}…</td></tr>`).join('')}</tbody></table></div><div><h3>审计时间线 <span class="subtle">${d.total} 项</span></h3>${d.audit_events.length?`<div class="timeline">${d.audit_events.map(x=>`<div class="timeline-item"><strong>${esc(x.event_type)}</strong><small>${esc(x.actor)} · ${new Date(x.created_at).toLocaleString()}</small><div class="subtle">${esc(x.reason||x.entity_type)}</div></div>`).join('')}</div>`:'<div class="empty">暂无审计事件</div>'}<div class="actions" style="justify-content:flex-end"><button class="btn small" ${d.offset<=0?'disabled':''} onclick="auditPage(-${limit})">上一页</button><button class="btn small" ${d.offset+d.limit>=d.total?'disabled':''} onclick="auditPage(${limit})">下一页</button></div></div></div>`}
window.auditPage=d=>{state.auditOffset=Math.max(0,state.auditOffset+d);projectWorkspace()};
async function refreshProjects(){const d=await api('/api/v1/projects');state.projects=d.projects||[]}
async function ensureProjects(){if(!state.projects.length){const d=await api('/api/v1/projects');state.projects=d.projects||[]}return state.projects}
function projectOptions(){return state.projects.map(p=>`<option value="${p.project_id}">${esc(p.title)} · ${esc(p.protocol_title||'')}</option>`).join('')}



init();

/* Core helpers published for the extracted domain modules (ADR-0002 split). */
window.head=head;window.statusClass=statusClass;window.stageLabel=stageLabel;window.workbenchActionLabel=workbenchActionLabel;window.ensureProjects=ensureProjects;window.refreshProjects=refreshProjects;window.projectOptions=projectOptions;window.stageLabels=stageLabels;window.offerLabels=offerLabels;window.projectStatusLabels=projectStatusLabels;window.icons=icons;